          "properties": {
            "visuals": {
              "type": "integer",
              "minimum": 1
            },
            "pullRequest": {
              "type": "integer",
              "minimum": 1
            },
            "reviewComment": {
              "type": "integer",
              "minimum": 1
            }
          }
        }
      }
    }
  }
